<?php
    $sql = "SELECT * FROM reviews WHERE user_id = ?";
    $stmt = $connect->prepare($sql);
    $stmt->execute([$USER['id']]);
    $reviews = $stmt->fetchAll(PDO::FETCH_ASSOC);

    $moderate = [];
    $accepted = [];
    $canceled = [];

    foreach($reviews as $review) {
        if($review['status'] == 'На модерации') array_push($moderate, $review);
        elseif($review['status'] == 'Принят') array_push($accepted, $review);
        elseif($review['status'] == 'Отклонен') array_push($canceled, $review);
    }

    if(isset($_POST['createReview'])) {
        if(empty($_POST['rate'])) $errors['rate'] = 'Укажите оценку товара';
        if(empty($_POST['text'])) $errors['text'] = 'Заполните текст отзыва';
        if(empty($errors)) {
            $sql = "UPDATE reviews SET rate = ?, text = ?, status = ? WHERE id = ?";
            $stmt = $connect->prepare($sql);
            $stmt->execute([$_POST['rate'], $_POST['text'], 'На модерации', $_GET['review']]);
            echo '<script>location.href="?page=profile&reviews"</script>';
        }
    }

    if(isset($_POST['deleteReview'])) {
        $sql = "DELETE FROM reviews WHERE id = ?";
        $stmt = $connect->prepare($sql);
        $stmt->execute([$_GET['delete']]);
        echo '<script>location.href="?page=profile&reviews"</script>';
    }
?>

